package com.nightbeam.donutshards.api;
import com.nightbeam.donutshards.model.*;import com.nightbeam.donutshards.transaction.TransactionService;import com.nightbeam.donutshards.zone.ZoneService;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.CopyOnWriteArrayList;
public final class DefaultDonutShardsApi implements DonutShardsApi {private final TransactionService tx;private final ZoneService zones;private final int tax;private final List<AntiCheatFlagProvider> providers=new CopyOnWriteArrayList<>();public DefaultDonutShardsApi(TransactionService tx,ZoneService zones,int tax){this.tx=tx;this.zones=zones;this.tax=tax;}public CompletionStage<Long> getBalance(UUID p){return tx.balance(p);}public OptionalLong getCachedBalance(UUID p){return tx.cached(p);}public CompletionStage<TransactionResult> setBalance(UUID p,long a,MutationContext c){return tx.set(p,a,c);}public CompletionStage<TransactionResult> addShards(UUID p,long a,MutationContext c){return tx.add(p,a,c);}public CompletionStage<TransactionResult> removeShards(UUID p,long a,MutationContext c){return tx.remove(p,a,c);}public CompletionStage<TransferResult> transfer(UUID f,UUID t,long a,MutationContext c){return tx.transfer(f,t,a,tax,c);}public CompletionStage<Optional<ShardTransaction>> getTransaction(UUID id){return tx.transaction(id);}public CompletionStage<PlayerStatistics> getPlayerStatistics(UUID p){return tx.statistics(p);}public boolean isInAfkZone(UUID p){return zones.isInZone(p);}public Optional<String> getCurrentAfkZone(UUID p){return zones.current(p);}public void registerAntiCheatProvider(AntiCheatFlagProvider p){Objects.requireNonNull(p);providers.removeIf(x->x.id().equals(p.id()));providers.add(p);}}
